// ========================================================================
// HMAC-Vorbereitung — extrahiert rawBody und expectedSignature.
// Der HMAC selbst wird im nachfolgenden Crypto-Node berechnet (kein
// require('crypto') noetig — das ist seit n8n 1.71 in der JS-Sandbox
// gesperrt: "Module 'crypto' is disallowed").
// ========================================================================

const item = $input.first();
const json = item.json;

// rawBody robust extrahieren — Webhook ist mit rawBody:true konfiguriert,
// also liegt der Body als binary an. Die Signatur muss byte-identisch zum
// Backend-Body sein (sonst HMAC-Mismatch).
let rawBodyString;
if (item.binary?.data?.data) {
  rawBodyString = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
} else if (typeof item.binary?.data === 'string') {
  rawBodyString = Buffer.from(item.binary.data, 'base64').toString('utf-8');
} else {
  // Fallback: re-stringify (nur fuer Edge-Cases ohne rawBody)
  rawBodyString = JSON.stringify(json.body ?? json);
}

const signatureHeader = json.headers?.['x-signature'] || '';
const expectedSignature = signatureHeader.startsWith('sha256=')
  ? signatureHeader.slice('sha256='.length)
  : '';

// Hartkodiertes Shared-Secret (= Secret im App-Notification-Ziel).
// NICHT $env nutzen: n8n mit Task-Runner blockt das ("access to env vars denied").
const secret = 'HMAC_SECRET_AUS_ADMIN_N8N_WEBHOOKS_EINTRAGEN';
const skipSignatureCheck = !secret;

// Wenn das Secret konfiguriert ist, MUSS ein Header da sein.
if (!skipSignatureCheck && !expectedSignature) {
  throw new Error('Fehlende oder ungueltige X-Signature');
}

return [{
  json: {
    ...json,
    rawBodyString,
    expectedSignature,
    skipSignatureCheck,
  },
}];

// ========================================================================
// Signatur-Vergleich nach dem Crypto-Node.
// Konstantzeit-aehnlicher Vergleich in pure JS — kein require('crypto') noetig.
// ========================================================================

const json = $input.first().json;
const expectedSignature = String(json.expectedSignature ?? '');
const computedHmac = String(json.computedHmac ?? '');
const skipSignatureCheck = json.skipSignatureCheck === true;

if (skipSignatureCheck) {
  return [{ json: { ...json, _signatureValid: true, _signatureSkipped: true } }];
}

if (expectedSignature.length !== computedHmac.length || expectedSignature.length === 0) {
  throw new Error('Ungueltige HMAC-Signatur');
}

let diff = 0;
for (let i = 0; i < expectedSignature.length; i++) {
  diff |= expectedSignature.charCodeAt(i) ^ computedHmac.charCodeAt(i);
}
if (diff !== 0) {
  throw new Error('Ungueltige HMAC-Signatur');
}

return [{ json: { ...json, _signatureValid: true } }];

// ========================================================================
// HTML-Mail: Verteilung zwischen den Schulen geaendert (NICHT gehaltsrelevant)
// Das Hauptdeputat (Gesamt-WS) bleibt gleich, nur die Aufteilung GES/GYM/BK
// verschiebt sich. CREDO Corporate Design -- Outlook-optimiert.
// ========================================================================

const data = $input.first().json;
const payload = data.body?.payload || data.payload || data;
const aenderungen = payload.aenderungen || [];
const count = payload.count || aenderungen.length;
const timestamp = data.body?.timestamp || data.timestamp;
const tsFormatted = timestamp
  ? new Date(timestamp).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' })
  : new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const monatsnamen = [
  '', 'Januar', 'Februar', 'März', 'April', 'Mai', 'Juni',
  'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'
];

const APP_URL = 'https://deputat.fes-credo.de';
const LINK_DEPUTATE = APP_URL + '/deputate';
const LINK_HISTORIE = APP_URL + '/historie';

// alt/neu je Schule: erste Periode (alt) -> letzte Periode (neu) des Monats.
function schuleAltNeu(a, schule) {
  if (!Array.isArray(a.perioden) || a.perioden.length === 0) return { alt: 0, neu: 0 };
  const first = a.perioden[0];
  const last = a.perioden[a.perioden.length - 1];
  return {
    alt: Number(first?.alt?.[schule] ?? 0),
    neu: Number(last?.neu?.[schule] ?? 0),
  };
}

// Zelle: unveraendert -> grau; sonst alt -> farbiger Pfeil neu.
function zelle(s) {
  const diff = s.neu - s.alt;
  if (Math.abs(diff) < 0.001) {
    return '<span style="color:#999999;">' + s.alt.toFixed(1) + '</span>';
  }
  const arrow = diff > 0 ? '▲' : '▼';
  const color = diff > 0 ? '#6BAA24' : '#E2001A';
  return '<span style="color:#575756;">' + s.alt.toFixed(1) + '</span> '
    + '<span style="color:' + color + ';font-weight:700;">' + arrow + ' ' + s.neu.toFixed(1) + '</span>';
}

const sorted = [...aenderungen].sort((x, y) => {
  const n = (x.vollname || '').localeCompare(y.vollname || '', 'de');
  if (n !== 0) return n;
  return (x.jahr - y.jahr) || (x.monat - y.monat);
});

const tdBase = 'padding:10px 14px;border-bottom:1px solid #E5E5E5;font-family:Montserrat,Arial,sans-serif;';
const rows = sorted.map(a => {
  const ges = schuleAltNeu(a, 'ges');
  const gym = schuleAltNeu(a, 'gym');
  const bk = schuleAltNeu(a, 'bk');
  const monat = monatsnamen[a.monat] || a.monat;
  return '\n    <tr>'
    + '\n      <td style="' + tdBase + 'font-size:14px;color:#333333;">' + (a.vollname || '–') + '</td>'
    + '\n      <td style="' + tdBase + 'font-size:13px;color:#777777;text-align:center;">' + monat + ' ' + a.jahr + '</td>'
    + '\n      <td style="' + tdBase + 'font-size:13px;text-align:center;">' + zelle(ges) + '</td>'
    + '\n      <td style="' + tdBase + 'font-size:13px;text-align:center;">' + zelle(gym) + '</td>'
    + '\n      <td style="' + tdBase + 'font-size:13px;text-align:center;">' + zelle(bk) + '</td>'
    + '\n    </tr>';
}).join('');

const thBase = 'padding:10px 14px;font-family:Montserrat,Arial,sans-serif;font-size:12px;font-weight:600;text-align:center;text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #E0E0E0;';

const html = '<!DOCTYPE html>'
+ '<html xmlns="http://www.w3.org/1999/xhtml" lang="de"><head>'
+ '<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
+ '<meta http-equiv="X-UA-Compatible" content="IE=edge">'
+ '<title>Verteilungsänderung -- CREDO Stellenist</title>'
+ '<!--[if mso]><noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript><![endif]-->'
+ '</head>'
+ '<body style="margin:0;padding:0;background-color:#F4F4F4;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;">'
+ '<!--[if mso]><table role="presentation" width="640" align="center" cellpadding="0" cellspacing="0" border="0"><tr><td><![endif]-->'
+ '<table role="presentation" align="center" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:680px;margin:20px auto;background-color:#FFFFFF;border-collapse:collapse;">'
// Header
+ '<tr><td style="background-color:#575756;padding:24px 30px;">'
+ '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
+ '<td style="font-family:Montserrat,Arial,sans-serif;font-size:20px;font-weight:700;color:#FFFFFF;letter-spacing:0.5px;">CREDO Stellenist</td>'
+ '<td style="font-family:Montserrat,Arial,sans-serif;font-size:12px;color:#BBBBBB;text-align:right;vertical-align:bottom;">Automatische Benachrichtigung</td>'
+ '</tr></table></td></tr>'
// Alert Bar (CREDO Blau #009AC6 -- Information)
+ '<tr><td style="background-color:#009AC6;padding:12px 30px;font-family:Montserrat,Arial,sans-serif;font-size:13px;font-weight:600;color:#FFFFFF;letter-spacing:0.3px;">'
+ count + ' Verteilungsänderung' + (count === 1 ? '' : 'en') + ' zwischen den Schulen</td></tr>'
// Content
+ '<tr><td style="padding:24px 30px 8px;">'
+ '<p style="font-family:Montserrat,Arial,sans-serif;font-size:14px;color:#575756;margin:0 0 8px;line-height:1.5;">'
+ 'Beim letzten Untis-Sync wurde' + (count === 1 ? '' : 'n') + ' <strong>' + count + '</strong> Verteilungswechsel zwischen Gesamtschule, Gymnasium und Berufskolleg erkannt.</p>'
+ '<p style="font-family:Montserrat,Arial,sans-serif;font-size:13px;color:#009AC6;margin:0 0 18px;line-height:1.5;font-weight:600;">'
+ 'Das Hauptdeputat (Gesamtstunden) der Lehrkraft bleibt unverändert &ndash; nicht gehaltsrelevant. Information für Stundenplanung und Schulleitungen.</p>'
// Tabelle
+ '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;border:1px solid #E5E5E5;">'
+ '<tr style="background-color:#F7F7F7;">'
+ '<th style="' + thBase + 'text-align:left;color:#575756;">Lehrkraft</th>'
+ '<th style="' + thBase + 'color:#575756;">Monat</th>'
+ '<th style="' + thBase + 'color:#6BAA24;">GES</th>'
+ '<th style="' + thBase + 'color:#C9A200;">GYM</th>'
+ '<th style="' + thBase + 'color:#5C82A5;">BK</th>'
+ '</tr>' + rows + '</table>'
+ '<p style="font-family:Montserrat,Arial,sans-serif;font-size:12px;color:#999999;margin:14px 0 0;line-height:1.5;">'
+ 'Werte in Wochenstunden. Grau = unverändert, ▲ mehr / ▼ weniger an dieser Schule.</p>'
+ '</td></tr>'
// Button
+ '<tr><td style="padding:18px 30px 8px;text-align:center;">'
+ '<!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" href="' + LINK_DEPUTATE + '" style="height:42px;v-text-anchor:middle;width:280px;" arcsize="10%" strokecolor="#575756" fillcolor="#575756"><center style="color:#ffffff;font-family:Montserrat,Arial,sans-serif;font-size:14px;font-weight:bold;">In CREDO Stellenist öffnen</center></v:roundrect><![endif]-->'
+ '<!--[if !mso]><!-->'
+ '<a href="' + LINK_DEPUTATE + '" target="_blank" style="display:inline-block;padding:11px 28px;background-color:#575756;color:#FFFFFF;font-family:Montserrat,Arial,sans-serif;font-size:14px;font-weight:600;text-decoration:none;border-radius:6px;line-height:20px;">In CREDO Stellenist öffnen</a>'
+ '<!--<![endif]--></td></tr>'
// Sekundaer-Link
+ '<tr><td style="padding:0 30px 22px;text-align:center;">'
+ '<a href="' + LINK_HISTORIE + '" target="_blank" style="font-family:Montserrat,Arial,sans-serif;font-size:12px;color:#575756;text-decoration:underline;">Zur Änderungs-Historie</a>'
+ '</td></tr>'
// Footer
+ '<tr><td style="background-color:#F7F7F7;padding:16px 30px;border-top:1px solid #E5E5E5;">'
+ '<p style="font-family:Montserrat,Arial,sans-serif;font-size:11px;color:#999999;margin:0;line-height:1.5;">'
+ 'Gesendet am ' + tsFormatted + ' &middot; CREDO Schulen &middot; Stellenist-Berechnung<br>'
+ 'Diese E-Mail wurde automatisch generiert. Bitte nicht antworten.</p></td></tr>'
+ '</table>'
+ '<!--[if mso]></td></tr></table><![endif]-->'
+ '</body></html>';

return [{
  json: {
    html,
    subject: 'CREDO Stellenist: ' + count + ' Verteilungsänderung' + (count === 1 ? '' : 'en') + ' (nicht gehaltsrelevant)',
    count
  }
}];
